// User Session Management (Anonymous Users)
// Generates and persists unique user ID in localStorage

const USER_ID_KEY = 'ai_tutor_user_id';

/**
 * Get or create anonymous user ID
 * Format: user_<timestamp>_<random>
 * Example: user_1738167000000_k3j9f2x1a
 */
export const getUserId = () => {
  // Check if user ID already exists
  let userId = localStorage.getItem(USER_ID_KEY);

  if (!userId) {
    // Generate new unique ID
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 11);
    userId = `user_${timestamp}_${random}`;

    // Save to localStorage (persists across browser sessions)
    localStorage.setItem(USER_ID_KEY, userId);
    console.log('✅ New user ID generated:', userId);
  } else {
    console.log('✅ Existing user ID found:', userId);
  }

  return userId;
};

/**
 * Clear user ID (for logout or reset)
 */
export const clearUserId = () => {
  localStorage.removeItem(USER_ID_KEY);
  console.log('🗑️ User ID cleared');
};

/**
 * Get short display name from user ID
 * Example: user_1738167000000_k3j9f2x1a -> User k3j
 */
export const getDisplayName = (userId) => {
  if (!userId) return 'Unknown';
  const parts = userId.split('_');
  return `User ${parts[2]?.substring(0, 3) || 'XXX'}`;
};
